#ifndef MATERIAL_SHARED_PULLBACK_H
#define MATERIAL_SHARED_PULLBACK_H
#include "material_shared_retained.h"
#include "material_shared_real_bound.h"
namespace shared_target {
struct Face {const sd::Compiled*map=nullptr;Plane plane;S vertex[3],bend[10],bulk[2],extension[3][2];};
// A real gradient cone about the ACTUAL stored affine P3 map.  The old
// ||F-I|| cone includes the resolved local rotation; it needlessly loses
// almost-parallel target directions.  Bounds below preserve the same
// analytic residuals, coefficients and fixed whole-source Taylor domain.
struct ShapeBound {Q value=0,gradient[2]={};};
struct ShapeBounds {ShapeBound q[2],edge[3][2];};
static ShapeBounds shape_bounds(const sd::Compiled&m){ShapeBounds out;const auto&base=m.base;const auto&t=base.state->triangle[base.source];Q delta[2]={};for(int a=0;a<3;a++)for(int k=0;k<2;k++)delta[k]=std::max(delta[k],sf::mag(base.vertex[a][k]-base.vertex[0][k]));auto q=sf::taylor_bound(base.vertex[0],delta,base.eps);for(int c=0;c<2;c++){S nodes[10];for(int a=0;a<10;a++)nodes[a]=m.qnode[a][c];auto p=sf::cubic_bound(base,nodes);out.q[c].value=sf::add(q.value[c],p.value);for(int j=0;j<2;j++)out.q[c].gradient[j]=sf::add(q.gradient[c][j],p.gradient[j]);}for(int e=0;e<3;e++){const auto&edge=base.edge[e];Q change[2]={sf::mag(edge.Dref[0]),sf::mag(edge.Dref[1])};auto r=sf::taylor_bound(edge.A,change,base.eps);sf::D parameter(S(Q(.5L),Q(.5L)),S(1),S(0));for(int c=0;c<2;c++){Q value=r.value[c],derivative=0;for(int j=0;j<2;j++)derivative=sf::add(derivative,sf::mul(r.gradient[c][j],change[j]));for(int a=0;a<4;a++){auto L=sf::lagrange(a,parameter);value=sf::add(value,sf::mul(sf::mag(L.v),sf::mag(m.qedge[e][a][c])));derivative=sf::add(derivative,sf::mul(sf::mag(L.x),sf::mag(m.qedge[e][a][c])));}out.edge[e][c].value=value;for(int j=0;j<2;j++){Q ds=sf::mag(base.grad[t.endpoint[e][0]][j]+base.grad[t.endpoint[e][1]][j]),b=sf::mag(base.grad[t.endpoint[e][1]][j]);out.edge[e][c].gradient[j]=sf::add(sf::mul(sf::mul(Q(4),ds),value),sf::mul(sf::add(b,ds),derivative));}}}return out;}
struct GradientCone {S gradient[2];Q nonaffine_value=0;};
// Signed Bernstein convex-hull enclosure for an exact cubic restricted to
// a reference subtriangle. Keeping its curvature avoids treating a small
// negative face at a corner as an unsigned full-triangle error bar.
static S cubic_range(const S*nodal){int at[4][4]={};for(int a=0;a<10;a++){int index[3];gfs_material_p3_index(a,index);at[index[1]][index[2]]=a;}S b[4][4]={};int vertex[3]={at[0][0],at[3][0],at[0][3]};for(int k=0;k<3;k++)b[k==1?3:0][k==2?3:0]=nodal[vertex[k]];for(int k=0;k<3;k++){int j=(k+1)%3,i1[3]={},i2[3]={};i1[k]=2;i1[j]=1;i2[k]=1;i2[j]=2;int p=at[i1[1]][i1[2]],q=at[i2[1]][i2[2]];b[i1[1]][i1[2]]=S(3)*nodal[p]-S(Q(1.5L))*nodal[q]-S(5)*nodal[vertex[k]]/S(6)+nodal[vertex[j]]/S(3);b[i2[1]][i2[2]]=S(3)*nodal[q]-S(Q(1.5L))*nodal[p]+nodal[vertex[k]]/S(3)-S(5)*nodal[vertex[j]]/S(6);}S boundary;for(int i=0;i<=3;i++)for(int j=0;i+j<=3;j++)if((i||j)&&i!=3&&j!=3&&!(i==1&&j==1))boundary=boundary+b[i][j];b[1][1]=(S(27)*nodal[at[1][1]]-nodal[vertex[0]]-nodal[vertex[1]]-nodal[vertex[2]]-S(3)*boundary)/S(6);Q lo=__builtin_huge_valq(),hi=-__builtin_huge_valq();for(int i=0;i<=3;i++)for(int j=0;i+j<=3;j++){lo=std::min(lo,sf::lower(b[i][j]));hi=std::max(hi,sf::upper(b[i][j]));}return sf::range(lo,hi);}
static S actual_face_range(const Face&f,const sd::Chart&chart,const ShapeBounds&shape){S nodal[10];const auto&t=f.map->base.state->triangle[f.map->base.source];for(int a=0;a<10;a++){int index[3];gfs_material_p3_index(a,index);S lambda[3];for(int k=0;k<3;k++)for(int j=0;j<3;j++)lambda[k]=lambda[k]+S(index[j])*chart.vertex[j][k]/S(3);S value=f.vertex[0];for(int j=1;j<3;j++)value=value+(f.vertex[j]-f.vertex[0])*lambda[j];for(int b=0;b<10;b++){int order[3];gfs_material_p3_index(b,order);S N(1);for(int k=0;k<3;k++)for(int j=0;j<order[k];j++)N=N*(S(3)*lambda[k]-S(j))/S(order[k]-j);S coefficient=f.bend[b];if(b==9)for(int k=0;k<2;k++)coefficient=coefficient-f.bulk[k]*sf::exact(t.bubble_shift[k]);value=value+coefficient*N;}nodal[a]=value;}S range=cubic_range(nodal);Q remainder=f.plane.input_offset_radius;for(int c=0;c<2;c++){remainder=sf::add(remainder,sf::mul(sf::mag(f.bulk[c]),shape.q[c].value));for(int e=0;e<3;e++)remainder=sf::add(remainder,sf::mul(sf::mag(f.extension[e][c]),shape.edge[e][c].value));}range.e=sf::add(range.e,remainder);return range;}
static GradientCone gradient_cone(const Face&f,const ShapeBounds&shape){GradientCone out;const auto&m=f.map->base;const auto&t=m.state->triangle[m.source];S nodes[10];for(int a=0;a<10;a++)nodes[a]=f.bend[a];for(int c=0;c<2;c++)nodes[9]=nodes[9]-f.bulk[c]*sf::exact(t.bubble_shift[c]);auto polynomial=sf::cubic_bound(m,nodes);out.nonaffine_value=polynomial.value;Q remainder[2]={polynomial.gradient[0],polynomial.gradient[1]};for(int j=0;j<2;j++)for(int a=1;a<3;a++)out.gradient[j]=out.gradient[j]+(f.vertex[a]-f.vertex[0])*m.grad[a][j];for(int c=0;c<2;c++){Q b=sf::mag(f.bulk[c]);out.nonaffine_value=sf::add(out.nonaffine_value,sf::mul(b,shape.q[c].value));for(int j=0;j<2;j++)remainder[j]=sf::add(remainder[j],sf::mul(b,shape.q[c].gradient[j]));for(int e=0;e<3;e++){Q b=sf::mag(f.extension[e][c]);out.nonaffine_value=sf::add(out.nonaffine_value,sf::mul(b,shape.edge[e][c].value));for(int j=0;j<2;j++)remainder[j]=sf::add(remainder[j],sf::mul(b,shape.edge[e][c].gradient[j]));}}for(int j=0;j<2;j++)out.gradient[j].e=sf::add(out.gradient[j].e,remainder[j]);return out;}
static Face pullback(const sd::Compiled&m,const Plane&p){Face out;out.map=&m;out.plane=p;const auto&t=m.base.state->triangle[m.base.source];const auto&state=*m.base.state;Exact nodal[10],bulk[2];for(int a=0;a<10;a++){const auto&v=state.coefficient[t.id[a]];nodal[a]=exact_value(p,Q(v.x[0]),Q(v.x[1]));if(a<3)out.vertex[a]=ball(nodal[a]);}for(int a=0;a<10;a++){int index[3];gfs_material_p3_index(a,index);Exact residual=Exact(3)*nodal[a];for(int j=0;j<3;j++)residual=residual-Exact(index[j])*nodal[j];out.bend[a]=ball(residual)/S(3);}for(int k=0;k<2;k++){for(int j=0;j<2;j++){const auto&v=state.coefficient[t.id[t.bubble_offset+j]];bulk[k]=bulk[k]+(p.en[0]*Exact(Q(v.x[0]))+p.en[1]*Exact(Q(v.x[1])))*Exact(Q(t.bubble_encode[j][k]));}out.bulk[k]=ball(bulk[k]);for(int e=0;e<3;e++){Exact coefficient=-bulk[k];for(int j=0;j<t.edge[e].rank;j++){const auto&v=state.coefficient[t.id[t.offset[e]+j]];coefficient=coefficient+(p.en[0]*Exact(Q(v.x[0]))+p.en[1]*Exact(Q(v.x[1])))*Exact(Q(t.edge[e].encode[j][k]));}out.extension[e][k]=ball(coefficient);}}return out;}
struct Frame {S A[2],D[2],E[2];};
static Frame frame(const sd::Compiled&m,const sd::Chart&chart,S t){Frame f;for(int k=0;k<2;k++){f.A[k]=m.base.vertex[chart.apex][k];S B,C;for(int j=0;j<3;j++){B=B+chart.vertex[1][j]*m.base.vertex[j][k];C=C+chart.vertex[2][j]*m.base.vertex[j][k];}f.E[k]=C-B;f.D[k]=(B-f.A[k])+t*f.E[k];}return f;}
static sd::Jet face(const Face&f,const sd::Chart&chart,S s,S t){auto b=sd::basis(*f.map,chart,s,t);sd::Jet value(f.vertex[0]);for(int j=1;j<3;j++)value=value+sd::Jet(f.vertex[j]-f.vertex[0])*sd::Jet(b.point.lambda[j],f.map->base.grad[j][0],f.map->base.grad[j][1]);for(int a=0;a<10;a++)value=value+sd::Jet(f.bend[a])*b.N[a];for(int k=0;k<2;k++){value=value+sd::Jet(f.bulk[k])*b.q[k];for(int e=0;e<3;e++)value=value+sd::Jet(f.extension[e][k])*b.E[e][k];}if(b.point.apex)value.v=f.vertex[chart.apex];value.v.e=sf::add(value.v.e,f.plane.input_offset_radius);auto r=frame(*f.map,chart,t);S dx[2][2];for(int k=0;k<2;k++){dx[0][k]=r.D[k];dx[1][k]=s*r.E[k];}sd::Jet out(value.v);for(int i=0;i<2;i++)for(int k=0;k<2;k++){out.g[i]=out.g[i]+value.g[k]*dx[i][k];for(int j=0;j<2;j++)for(int l=0;l<2;l++)out.H[i][j]=out.H[i][j]+value.H[k][l]*dx[i][k]*dx[j][l];}for(int k=0;k<2;k++){out.H[0][1]=out.H[0][1]+value.g[k]*r.E[k];out.H[1][0]=out.H[1][0]+value.g[k]*r.E[k];}return out;}
// Cartesian derivatives of the same projected field, at a correlated
// (s,q) point. q and s are independent reference coordinates here.
static sd::Jet face_q(const Face&f,const sd::Chart&chart,S s,const sd::AffineAngular&coordinate){
    auto b=sd::basis(*f.map,chart,s,S(),&coordinate);S nodal[3];for(int a=0;a<3;a++)for(int j=0;j<3;j++)nodal[a]=nodal[a]+chart.vertex[a][j]*f.vertex[j];
    S v=sd::affine_coordinate(nodal[0],nodal[1],nodal[2],s,coordinate);
    S gx,gy;for(int j=1;j<3;j++){gx=gx+(f.vertex[j]-f.vertex[0])*f.map->base.grad[j][0];gy=gy+(f.vertex[j]-f.vertex[0])*f.map->base.grad[j][1];}
    sd::Jet value(v,gx,gy);for(int a=0;a<10;a++)value=value+sd::Jet(f.bend[a])*b.N[a];for(int k=0;k<2;k++){value=value+sd::Jet(f.bulk[k])*b.q[k];for(int e=0;e<3;e++)value=value+sd::Jet(f.extension[e][k])*b.E[e][k];}value.v.e=sf::add(value.v.e,f.plane.input_offset_radius);
    auto r=frame(*f.map,chart,S(0));S dx[2][2];for(int k=0;k<2;k++){dx[0][k]=r.D[k];dx[1][k]=r.E[k];}sd::Jet out(value.v);for(int i=0;i<2;i++)for(int k=0;k<2;k++){out.g[i]=out.g[i]+value.g[k]*dx[i][k];for(int j=0;j<2;j++)for(int l=0;l<2;l++)out.H[i][j]=out.H[i][j]+value.H[k][l]*dx[i][k]*dx[j][l];}return out;
}
// Closed real Cartesian point evaluation may use the proven C3 vertex
// derivative. No inverse of the singular Duffy coordinate Jacobian is used.
static sd::Point real_point(const sd::Compiled&m,Q X,Q Y){for(int a=0;a<3;a++)if(X==m.base.vertex[a][0].n&&Y==m.base.vertex[a][1].n)return sd::evaluate(m,sd::charts(m)[2*a],S(0),S(0));return sd::cartesian(m,S(X),S(Y));}
static sf::Inverse inverse_reference(const sd::Compiled&m,const sf::RealBounds&bound,S x,S y){need(bound.L<1,"real pullback inverse requires original injectivity bound");Q X=m.base.anchor[0],Y=m.base.anchor[1];for(int it=0;it<16;it++){auto q=real_point(m,X,Y).field;Q det=q.J.n,fx=q.position[0].n-x.n,fy=q.position[1].n-y.n,dx=(q.F[3].n*fx-q.F[1].n*fy)/det,dy=(-q.F[2].n*fx+q.F[0].n*fy)/det,step=1;auto lambda=sf::barycentric(m.base,S(X),S(Y));for(int a=0;a<3;a++){Q d=m.base.grad[a][0].n*dx+m.base.grad[a][1].n*dy;if(d>=sf::lower(lambda[a].v)&&d>0)step=std::min(step,Q(.5L)*sf::lower(lambda[a].v)/d);}need(step>0,"real inverse iterate remains in source");X-=step*dx;Y-=step*dy;if(std::max(fabsq(step*dx),fabsq(step*dy))<1e-29Q)break;}auto q=real_point(m,X,Y).field;Q residual=std::max(sf::mag(q.position[0]-x),sf::mag(q.position[1]-y));sf::Inverse out;out.L=bound.L;out.radius=sf::quotient(sf::mul(Q(2),residual),mf::FP<Q>::down(Q(1)-bound.L));out.X=S(X,out.radius);out.Y=S(Y,out.radius);auto lambda=sf::barycentric(m.base,out.X,out.Y);out.inside=sf::lower(lambda[0].v)>0&&sf::lower(lambda[1].v)>0&&sf::lower(lambda[2].v)>0;need(out.inside,"real pullback inverse contraction box remains inside original source");return out;}
struct ChartCoordinate {S s,t;bool vertex=false;};
static ChartCoordinate coordinates(const sd::Compiled&m,const sd::Chart&chart,S X,S Y){auto l=sf::barycentric(m.base,X,Y);int i=(chart.apex+1)%3,j=(chart.apex+2)%3;S B0=chart.vertex[1][i],B1=chart.vertex[1][j],C0=chart.vertex[2][i],C1=chart.vertex[2][j],det=B0*C1-B1*C0;need(sf::lower(det)>0,"positive general apex-chart barycentric determinant");S u=(l[i].v*C1-l[j].v*C0)/det,v=(B0*l[j].v-B1*l[i].v)/det;ChartCoordinate out;out.s=u+v;need(sf::lower(out.s)>0,"chart apex coordinate has an explicit vertex event");out.t=v/out.s;return out;}
}
#endif
